@import "tailwindcss";

@theme inline {
  /* ──────────────────────────────────────────────────────────
     BRAND SWATCHES (single source of raw hex — Vega owns these)
  ────────────────────────────────────────────────────────── */
  --color-ink-black: #0a0a0f;
  --color-electric-purple: #7c3aed;

  /* ──────────────────────────────────────────────────────────
     SEMANTIC PALETTE — LIGHT MODE
  ────────────────────────────────────────────────────────── */
  --color-background: oklch(99% 0 0);
  --color-foreground: oklch(10% 0.01 260);
  --color-card: oklch(99% 0 0);
  --color-card-foreground: oklch(10% 0.01 260);
  --color-popover: oklch(99% 0 0);
  --color-popover-foreground: oklch(10% 0.01 260);

  --color-primary: oklch(52% 0.24 292);
  --color-primary-foreground: oklch(99% 0 0);

  --color-secondary: oklch(95% 0.01 264);
  --color-secondary-foreground: oklch(25% 0.02 264);

  --color-muted: oklch(96% 0.01 264);
  --color-muted-foreground: oklch(55% 0.02 264);

  --color-accent: oklch(95% 0.02 292);
  --color-accent-foreground: oklch(32% 0.14 292);

  --color-destructive: oklch(59% 0.22 27);
  --color-destructive-foreground: oklch(99% 0 0);

  --color-border: oklch(90% 0.01 264);
  --color-input: oklch(90% 0.01 264);
  --color-ring: oklch(52% 0.24 292);

  /* ──────────────────────────────────────────────────────────
     SHADOWS — custom (never use Tailwind default shadow-sm/md)
  ────────────────────────────────────────────────────────── */
  --shadow-soft: 0 1px 3px 0 oklch(10% 0 0 / 0.06), 0 1px 2px -1px oklch(10% 0 0 / 0.06);
  --shadow-card: 0 1px 4px 0 oklch(10% 0 0 / 0.08), 0 2px 8px -2px oklch(10% 0 0 / 0.06);
  --shadow-soft-md: 0 4px 12px -2px oklch(10% 0 0 / 0.08), 0 2px 6px -2px oklch(10% 0 0 / 0.06);

  /* ──────────────────────────────────────────────────────────
     RADIUS
  ────────────────────────────────────────────────────────── */
  --radius: 0.5rem;
  --radius-sm: 0.25rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;

  /* ──────────────────────────────────────────────────────────
     TYPOGRAPHY
  ────────────────────────────────────────────────────────── */
  --font-sans: var(--font-geist-sans), system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-mono: var(--font-geist-mono), "Fira Code", "Cascadia Code", ui-monospace, monospace;

  /* ──────────────────────────────────────────────────────────
     SIDEBAR TOKENS (shadcn sidebar primitives)
  ────────────────────────────────────────────────────────── */
  --sidebar-background: oklch(97% 0.005 264);
  --sidebar-foreground: oklch(25% 0.02 264);
  --sidebar-primary: oklch(52% 0.24 292);
  --sidebar-primary-foreground: oklch(99% 0 0);
  --sidebar-accent: oklch(93% 0.02 292);
  --sidebar-accent-foreground: oklch(32% 0.14 292);
  --sidebar-border: oklch(90% 0.01 264);
  --sidebar-ring: oklch(52% 0.24 292);
  --sidebar-width: 16rem;
  --sidebar-width-mobile: 18rem;
}

@layer base {
  *,
  *::before,
  *::after {
    border-color: var(--color-border);
    outline-color: var(--color-ring);
  }

  html {
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
  }

  body {
    background-color: var(--color-background);
    color: var(--color-foreground);
    font-family: var(--font-sans);
  }
}

/* ──────────────────────────────────────────────────────────
   DARK MODE OVERRIDES (separate palette — NOT inverted)
────────────────────────────────────────────────────────── */
.dark {
  --color-background: oklch(9% 0.015 264);
  --color-foreground: oklch(95% 0.005 264);
  --color-card: oklch(12% 0.015 264);
  --color-card-foreground: oklch(95% 0.005 264);
  --color-popover: oklch(12% 0.015 264);
  --color-popover-foreground: oklch(95% 0.005 264);

  --color-primary: oklch(62% 0.24 292);
  --color-primary-foreground: oklch(99% 0 0);

  --color-secondary: oklch(18% 0.02 264);
  --color-secondary-foreground: oklch(85% 0.01 264);

  --color-muted: oklch(18% 0.02 264);
  --color-muted-foreground: oklch(60% 0.02 264);

  --color-accent: oklch(20% 0.04 292);
  --color-accent-foreground: oklch(75% 0.14 292);

  --color-destructive: oklch(55% 0.22 27);
  --color-destructive-foreground: oklch(99% 0 0);

  --color-border: oklch(22% 0.02 264);
  --color-input: oklch(22% 0.02 264);
  --color-ring: oklch(62% 0.24 292);

  --shadow-soft: 0 1px 3px 0 oklch(0% 0 0 / 0.3), 0 1px 2px -1px oklch(0% 0 0 / 0.3);
  --shadow-card: 0 1px 4px 0 oklch(0% 0 0 / 0.4), 0 2px 8px -2px oklch(0% 0 0 / 0.3);
  --shadow-soft-md: 0 4px 12px -2px oklch(0% 0 0 / 0.4), 0 2px 6px -2px oklch(0% 0 0 / 0.3);

  --sidebar-background: oklch(11% 0.015 264);
  --sidebar-foreground: oklch(85% 0.01 264);
  --sidebar-primary: oklch(62% 0.24 292);
  --sidebar-primary-foreground: oklch(99% 0 0);
  --sidebar-accent: oklch(18% 0.04 292);
  --sidebar-accent-foreground: oklch(75% 0.14 292);
  --sidebar-border: oklch(22% 0.02 264);
  --sidebar-ring: oklch(62% 0.24 292);
}

import type { Metadata } from 'next'
import { Geist, Geist_Mono } from 'next/font/google'
import { Toaster } from 'sonner'
import { ThemeProvider } from 'next-themes'
import './globals.css'

const geistSans = Geist({
  variable: '--font-geist-sans',
  subsets: ['latin'],
})

const geistMono = Geist_Mono({
  variable: '--font-geist-mono',
  subsets: ['latin'],
})

export const metadata: Metadata = {
  title: {
    default: 'InkOS — Tattoo Studio OS',
    template: '%s | InkOS',
  },
  description: 'The operating system for modern tattoo studios.',
  robots: {
    index: false,
    follow: false,
  },
}

interface RootLayoutProps {
  children: React.ReactNode
}

export default function RootLayout({ children }: RootLayoutProps) {
  return (
    <html
      lang="en"
      suppressHydrationWarning
      className={`${geistSans.variable} ${geistMono.variable}`}
    >
      <body className="bg-background text-foreground antialiased">
        <ThemeProvider
          attribute="class"
          defaultTheme="dark"
          enableSystem
          disableTransitionOnChange
        >
          {children}
          <Toaster
            position="bottom-right"
            richColors
            closeButton
            duration={4000}
          />
        </ThemeProvider>
      </body>
    </html>
  )
}
