import pino from 'pino'

/**
 * Structured pino logger.
 *
 * In production (Railway), outputs JSON that Railway aggregates and makes
 * searchable. In development, pino-pretty formats the output for readability.
 *
 * NEVER use console.log in production code — ESLint will block it.
 */
export const logger = pino({
  level: process.env.LOG_LEVEL ?? 'info',
  formatters: {
    level: (label) => ({ level: label }),
  },
  base: {
    env: process.env.NEXT_PUBLIC_APP_ENV ?? 'development',
    service: 'inkos-web',
    version: process.env.RAILWAY_DEPLOYMENT_ID ?? 'local',
  },
  redact: {
    paths: [
      'req.headers.authorization',
      'req.headers.cookie',
      '*.password',
      '*.token',
      '*.api_key',
      '*.apiKey',
      '*.secret',
      '*.webhook_key',
    ],
    censor: '[REDACTED]',
  },
  timestamp: pino.stdTimeFunctions.isoTime,
  ...(process.env.NODE_ENV === 'development' && {
    transport: {
      target: 'pino-pretty',
      options: {
        colorize: true,
        translateTime: 'HH:MM:ss',
        ignore: 'pid,hostname',
      },
    },
  }),
})

/**
 * Create a child logger with request-scoped context.
 */
export function requestLogger(requestId: string) {
  return logger.child({ requestId })
}
