import type { Json } from './supabase/types'

/**
 * Audit log helper.
 *
 * Writes to the audit_log table via the service-role client (bypasses RLS).
 * Every admin action, billing event, and sensitive data access should be logged here.
 *
 * Failures are logged but never throw — audit failures must not break the main flow.
 */
export async function logAuditAction(
  actorId: string | null,
  action: string,
  target: { type: string; id: string } | null,
  details: Json | null,
  studioId: string | null = null
): Promise<void> {
  try {
    // Lazy import to avoid circular deps and to keep this callable from edge runtimes
    const { createServiceRoleClient } = await import('./supabase/server')
    const supabase = createServiceRoleClient()

    await supabase.from('audit_log').insert({
      actor_id: actorId,
      action,
      target_type: target?.type ?? null,
      target_id: target?.id ?? null,
      studio_id: studioId,
      details,
    })
  } catch (err) {
    // Audit failures must not break the primary operation
    const { logger } = await import('./logger')
    logger.error({ err, action, actorId }, 'audit log write failed')
  }
}

import type { NextConfig } from 'next'

const isDev = process.env.NODE_ENV !== 'production'

const securityHeaders = [
  {
    key: 'Strict-Transport-Security',
    value: 'max-age=63072000; includeSubDomains; preload',
  },
  {
    key: 'X-Frame-Options',
    value: 'DENY',
  },
  {
    key: 'X-Content-Type-Options',
    value: 'nosniff',
  },
  {
    key: 'Referrer-Policy',
    value: 'origin-when-cross-origin',
  },
  {
    key: 'Permissions-Policy',
    value: 'camera=(), microphone=(), geolocation=()',
  },
  {
    key: 'X-DNS-Prefetch-Control',
    value: 'on',
  },
  {
    key: 'Content-Security-Policy',
    value: [
      "default-src 'self'",
      `script-src 'self' 'unsafe-inline' ${isDev ? "'unsafe-eval'" : ''} https://app.posthog.com https://cdn.sentry.io`,
      "style-src 'self' 'unsafe-inline'",
      `img-src 'self' data: blob: https://*.supabase.co ${isDev ? 'http://127.0.0.1:54321' : ''}`,
      "font-src 'self'",
      `connect-src 'self' https://*.supabase.co https://app.posthog.com https://api.dodopayments.com https://*.sentry.io wss://*.supabase.co ${isDev ? "http://127.0.0.1:54321 ws://127.0.0.1:54321 ws://localhost:3100 http://localhost:3100" : ''}`,
      "frame-ancestors 'none'",
      "worker-src 'self' blob:",
    ].join('; '),
  },
]

const nextConfig: NextConfig = {
  output: 'standalone',
  reactStrictMode: true,
  experimental: {},
  images: {
    remotePatterns: [
      {
        protocol: 'https',
        hostname: '*.supabase.co',
      },
    ],
  },
  async headers() {
    return [
      {
        source: '/:path*',
        headers: securityHeaders,
      },
    ]
  },
  typescript: {
    ignoreBuildErrors: false,
  },
}

export default nextConfig
