@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";

@custom-variant dark (&:is(.dark *));

@theme inline {
  /* ──────────────────────────────────────────────────────────
     BRAND SWATCHES (single source of raw hex — Vega owns these)
  ────────────────────────────────────────────────────────── */
  --color-ink-black: #0a0a0f;
  --color-electric-purple: #7c3aed;

  /* ──────────────────────────────────────────────────────────
     SEMANTIC PALETTE — LIGHT MODE
  ────────────────────────────────────────────────────────── */
  --color-background: oklch(99% 0 0);
  --color-foreground: oklch(10% 0.01 260);
  --color-card: oklch(99% 0 0);
  --color-card-foreground: oklch(10% 0.01 260);
  --color-popover: oklch(99% 0 0);
  --color-popover-foreground: oklch(10% 0.01 260);

  --color-primary: oklch(52% 0.24 292);
  --color-primary-foreground: oklch(99% 0 0);

  --color-secondary: oklch(95% 0.01 264);
  --color-secondary-foreground: oklch(25% 0.02 264);

  --color-muted: oklch(96% 0.01 264);
  --color-muted-foreground: oklch(55% 0.02 264);

  --color-accent: oklch(95% 0.02 292);
  --color-accent-foreground: oklch(32% 0.14 292);

  --color-destructive: oklch(59% 0.22 27);
  --color-destructive-foreground: oklch(99% 0 0);

  --color-border: oklch(90% 0.01 264);
  --color-input: oklch(90% 0.01 264);
  --color-ring: oklch(52% 0.24 292);

  /* ──────────────────────────────────────────────────────────
     SHADOWS — custom (never use Tailwind default shadow-sm/md)
  ────────────────────────────────────────────────────────── */
  --shadow-soft: 0 1px 3px 0 oklch(10% 0 0 / 0.06), 0 1px 2px -1px oklch(10% 0 0 / 0.06);
  --shadow-card: 0 1px 4px 0 oklch(10% 0 0 / 0.08), 0 2px 8px -2px oklch(10% 0 0 / 0.06);
  --shadow-soft-md: 0 4px 12px -2px oklch(10% 0 0 / 0.08), 0 2px 6px -2px oklch(10% 0 0 / 0.06);

  /* ──────────────────────────────────────────────────────────
     RADIUS
  ────────────────────────────────────────────────────────── */
  --radius: 0.5rem;
  --radius-sm: 0.25rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;

  /* ──────────────────────────────────────────────────────────
     TYPOGRAPHY
  ────────────────────────────────────────────────────────── */
  --font-sans: var(--font-geist-sans), system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-mono: var(--font-geist-mono), "Fira Code", "Cascadia Code", ui-monospace, monospace;

  /* ──────────────────────────────────────────────────────────
     SIDEBAR TOKENS (shadcn sidebar primitives)
  ────────────────────────────────────────────────────────── */
  --sidebar: oklch(97% 0.005 264);
  --sidebar-background: oklch(97% 0.005 264);
  --sidebar-foreground: oklch(25% 0.02 264);
  --sidebar-primary: oklch(52% 0.24 292);
  --sidebar-primary-foreground: oklch(99% 0 0);
  --sidebar-accent: oklch(93% 0.02 292);
  --sidebar-accent-foreground: oklch(32% 0.14 292);
  --sidebar-border: oklch(90% 0.01 264);
  --sidebar-ring: oklch(52% 0.24 292);
  --sidebar-width: 16rem;
  --sidebar-width-mobile: 18rem;
  --sidebar-width-icon: 3.5rem;

  /* shadcn token aliases */
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);

  /* ──────────────────────────────────────────────────────────
     STATUS BADGES — tattoo booking lifecycle
  ────────────────────────────────────────────────────────── */
  --color-status-pending: oklch(70% 0.16 72);
  --color-status-confirmed: oklch(62% 0.24 292);
  --color-status-in-progress: oklch(60% 0.2 200);
  --color-status-completed: oklch(58% 0.18 145);
  --color-status-cancelled: oklch(55% 0.02 264);
  --color-status-no-show: oklch(55% 0.22 27);

  /* ──────────────────────────────────────────────────────────
     NEON ACCENT
  ────────────────────────────────────────────────────────── */
  --color-neon-purple: oklch(72% 0.28 292);
  --color-neon-purple-glow: 0 0 20px oklch(72% 0.28 292 / 0.4);

  /* ──────────────────────────────────────────────────────────
     ANIMATIONS
  ────────────────────────────────────────────────────────── */
  --animate-fade-in-up: fade-in-up 0.35s ease-out;
  --animate-fade-in: fade-in 0.2s ease-out;
  --animate-slide-in-right: slide-in-right 0.25s ease-out;

  @keyframes fade-in-up {
    from { opacity: 0; transform: translateY(6px); }
    to   { opacity: 1; transform: translateY(0); }
  }
  @keyframes fade-in {
    from { opacity: 0; }
    to   { opacity: 1; }
  }
  @keyframes slide-in-right {
    from { opacity: 0; transform: translateX(8px); }
    to   { opacity: 1; transform: translateX(0); }
  }

  /* ──────────────────────────────────────────────────────────
     ONBOARDING PROGRESS
  ────────────────────────────────────────────────────────── */
  --color-onboarding-track: oklch(22% 0.02 264);
  --color-onboarding-fill: oklch(62% 0.24 292);
}

@layer base {
  *,
  *::before,
  *::after {
    border-color: var(--color-border);
    outline-color: var(--color-ring);
  }

  html {
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
  }

  body {
    background-color: var(--color-background);
    color: var(--color-foreground);
    font-family: var(--font-sans);
  }
}

/* ──────────────────────────────────────────────────────────
   DARK MODE OVERRIDES (separate palette — NOT inverted)
────────────────────────────────────────────────────────── */
.dark {
  --color-background: oklch(9% 0.015 264);
  --color-foreground: oklch(95% 0.005 264);
  --color-card: oklch(12% 0.015 264);
  --color-card-foreground: oklch(95% 0.005 264);
  --color-popover: oklch(12% 0.015 264);
  --color-popover-foreground: oklch(95% 0.005 264);

  --color-primary: oklch(62% 0.24 292);
  --color-primary-foreground: oklch(99% 0 0);

  --color-secondary: oklch(18% 0.02 264);
  --color-secondary-foreground: oklch(85% 0.01 264);

  --color-muted: oklch(18% 0.02 264);
  --color-muted-foreground: oklch(60% 0.02 264);

  --color-accent: oklch(20% 0.04 292);
  --color-accent-foreground: oklch(75% 0.14 292);

  --color-destructive: oklch(55% 0.22 27);
  --color-destructive-foreground: oklch(99% 0 0);

  --color-border: oklch(22% 0.02 264);
  --color-input: oklch(22% 0.02 264);
  --color-ring: oklch(62% 0.24 292);

  --shadow-soft: 0 1px 3px 0 oklch(0% 0 0 / 0.3), 0 1px 2px -1px oklch(0% 0 0 / 0.3);
  --shadow-card: 0 1px 4px 0 oklch(0% 0 0 / 0.4), 0 2px 8px -2px oklch(0% 0 0 / 0.3);
  --shadow-soft-md: 0 4px 12px -2px oklch(0% 0 0 / 0.4), 0 2px 6px -2px oklch(0% 0 0 / 0.3);

  --sidebar: oklch(11% 0.015 264);
  --sidebar-background: oklch(11% 0.015 264);
  --sidebar-foreground: oklch(85% 0.01 264);
  --sidebar-primary: oklch(62% 0.24 292);
  --sidebar-primary-foreground: oklch(99% 0 0);
  --sidebar-accent: oklch(18% 0.04 292);
  --sidebar-accent-foreground: oklch(75% 0.14 292);
  --sidebar-border: oklch(22% 0.02 264);
  --sidebar-ring: oklch(62% 0.24 292);
}

@layer components {
  /* ── Sidebar active state (CSS selector, not JS state) ── */
  [data-sidebar="menu-button"][data-active="true"] {
    background-color: oklch(62% 0.24 292 / 0.12);
    color: oklch(75% 0.18 292);
  }
  [data-sidebar="menu-button"][data-active="true"] svg {
    color: oklch(75% 0.18 292);
  }
  [data-sidebar="menu-button"][data-active="true"]:hover {
    background-color: oklch(62% 0.24 292 / 0.18);
  }

  /* ── Status badge variants ── */
  .badge-pending     { background-color: oklch(70% 0.16 72 / 0.12); color: oklch(70% 0.16 72); }
  .badge-confirmed   { background-color: oklch(62% 0.24 292 / 0.12); color: oklch(75% 0.18 292); }
  .badge-in-progress { background-color: oklch(60% 0.2 200 / 0.12); color: oklch(60% 0.2 200); }
  .badge-completed   { background-color: oklch(58% 0.18 145 / 0.12); color: oklch(58% 0.18 145); }
  .badge-cancelled   { background-color: oklch(55% 0.02 264 / 0.12); color: oklch(60% 0.02 264); }
  .badge-no-show     { background-color: oklch(55% 0.22 27 / 0.12); color: oklch(65% 0.2 27); }

  /* ── KPI card subtle purple glow on hover ── */
  .kpi-card-hover {
    transition: box-shadow 150ms ease-out, transform 150ms ease-out;
  }
  .kpi-card-hover:hover {
    box-shadow: var(--shadow-soft-md), 0 0 0 1px oklch(62% 0.24 292 / 0.15);
    transform: translateY(-1px);
  }

  /* ── Onboarding step indicator ── */
  .onboarding-step-active {
    background-color: oklch(62% 0.24 292);
    box-shadow: 0 0 12px oklch(62% 0.24 292 / 0.5);
  }
  .onboarding-step-done {
    background-color: oklch(58% 0.18 145);
  }
  .onboarding-step-future {
    background-color: oklch(22% 0.02 264);
    border: 1px solid oklch(30% 0.02 264);
  }
}

