input.content:
import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

/**
 * Merge Tailwind CSS class names without conflicts.
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

/**
 * Format a currency amount from cents to a display string.
 */
export function formatCurrency(cents: number, currency = 'USD', locale = 'en-US'): string {
  return new Intl.NumberFormat(locale, {
    style: 'currency',
    currency,
    minimumFractionDigits: 0,
    maximumFractionDigits: 2,
  }).format(cents / 100)
}

/**
 * Format a date for display.
 */
export function formatDate(date: Date | string, options?: Intl.DateTimeFormatOptions): string {
  const d = typeof date === 'string' ? new Date(date) : date
  return new Intl.DateTimeFormat('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    ...options,
  }).format(d)
}

/**
 * Generate a URL-safe slug from a string.
 */
export function slugify(input: string): string {
  return input
    .toLowerCase()
    .trim()
    .replace(/[^\w\s-]/g, '')
    .replace(/[\s_-]+/g, '-')
    .replace(/^-+|-+$/g, '')
}

/**
 * Truncate a string to a maximum length with an ellipsis.
 */
export function truncate(str: string, maxLength: number): string {
  if (str.length <= maxLength) return str
  return `${str.slice(0, maxLength - 3)}...`
}

/**
 * Type guard to check if a value is a non-null object.
 */
export function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

/**
 * Server-side feature gating.
 *
 * Returns whether a studio on a given plan tier has access to a feature.
 * For API routes: call requireFeature() to return a 403 response automatically.
 */

export type PlanTier = 'solo' | 'studio' | 'pro' | 'enterprise'

const PLAN_ORDER: Record<PlanTier, number> = {
  solo: 0,
  studio: 1,
  pro: 2,
  enterprise: 3,
}

/** Minimum plan required for each feature key */
const FEATURE_MIN_PLAN: Record<string, PlanTier> = {
  inventory: 'studio',
  commissions: 'studio',
  payroll: 'pro',
  ai_design: 'pro',
  guest_artists: 'pro',
  eu_reach: 'pro',
  multi_location: 'pro',
  white_label: 'enterprise',
  api_access: 'enterprise',
}

/**
 * Returns true if the given plan includes the feature.
 */
export function hasFeature(plan: PlanTier, feature: string): boolean {
  const minPlan = FEATURE_MIN_PLAN[feature]
  if (!minPlan) return true // unknown feature = available everywhere
  return PLAN_ORDER[plan] >= PLAN_ORDER[minPlan]
}

/**
 * Returns the minimum plan required for a feature, or null if always available.
 */
export function requiredPlanFor(feature: string): PlanTier | null {
  return FEATURE_MIN_PLAN[feature] ?? null
}

/**
 * Throws a structured error if the plan doesn't include the feature.
 * Use in API Route Handlers:
 *   const guard = requireFeature(studioplan, 'ai_design')
 *   if (guard) return guard
 */
export function requireFeature(
  plan: PlanTier,
  feature: string,
): Response | null {
  if (hasFeature(plan, feature)) return null
  const required = FEATURE_MIN_PLAN[feature] ?? 'pro'
  return Response.json(
    { error: 'Feature not available on current plan', requiredPlan: required },
    { status: 403 },
  )
}

/**
 * Server-side nav filtering.
 *
 * Takes the user's role, plan tier, and location count.
 * Returns the filtered NavGroup[] that the user is allowed to see.
 *
 * Filtering happens server-side so the sidebar never shows items the user
 * shouldn't see — no layout flicker from client-side CSS hide.
 */

import type { NavGroup, NavRole } from '@/components/app/sidebar/nav-config'
import { APP_NAV } from '@/components/app/sidebar/nav-config'
import type { PlanTier } from '@/lib/billing/feature-gate'

interface GetNavItemsOptions {
  role: NavRole
  plan: PlanTier
  locationCount: number
}

/**
 * Returns nav groups visible to the given role, filtered by role + location condition.
 * Items are NOT removed based on plan — gated items remain with a badge.
 */
export function getNavItems({ role, locationCount }: GetNavItemsOptions): NavGroup[] {
  return APP_NAV.filter((group) => {
    // Hide LOCATIONS group if only one location
    if (group.condition === 'multi-location' && locationCount <= 1) return false
    return true
  }).map((group) => ({
    ...group,
    items: group.items.filter((item) => item.requiredRoles.includes(role)),
  })).filter((group) => group.items.length > 0)
}

/**
 * Centralized query key factory.
 *
 * All TanStack Query keys are defined here to prevent typos,
 * enable precise invalidation, and provide IntelliSense.
 */

export const queryKeys = {
  dashboard: {
    all: () => ['dashboard'] as const,
    kpis: (studioId: string) => [...queryKeys.dashboard.all(), 'kpis', studioId] as const,
    schedule: (studioId: string, date: string) =>
      [...queryKeys.dashboard.all(), 'schedule', studioId, date] as const,
    activity: (studioId: string) =>
      [...queryKeys.dashboard.all(), 'activity', studioId] as const,
    alerts: (studioId: string) =>
      [...queryKeys.dashboard.all(), 'alerts', studioId] as const,
  },
  studios: {
    all: () => ['studios'] as const,
    detail: (studioId: string) => [...queryKeys.studios.all(), studioId] as const,
    members: (studioId: string) => [...queryKeys.studios.detail(studioId), 'members'] as const,
    locations: (studioId: string) =>
      [...queryKeys.studios.detail(studioId), 'locations'] as const,
  },
  appointments: {
    all: () => ['appointments'] as const,
    list: (studioId: string, filters?: Record<string, unknown>) =>
      [...queryKeys.appointments.all(), studioId, filters] as const,
    detail: (id: string) => [...queryKeys.appointments.all(), id] as const,
  },
  clients: {
    all: () => ['clients'] as const,
    list: (studioId: string, filters?: Record<string, unknown>) =>
      [...queryKeys.clients.all(), studioId, filters] as const,
    detail: (id: string) => [...queryKeys.clients.all(), id] as const,
  },
  artists: {
    all: () => ['artists'] as const,
    list: (studioId: string) => [...queryKeys.artists.all(), studioId] as const,
    detail: (id: string) => [...queryKeys.artists.all(), id] as const,
  },
} as const

import { QueryClient } from '@tanstack/react-query'

/**
 * Creates a new QueryClient with production-ready defaults.
 *
 * Used in QueryProvider to create per-request client on the server
 * and a singleton client on the browser.
 */
export function makeQueryClient(): QueryClient {
  return new QueryClient({
    defaultOptions: {
      queries: {
        // Data is considered fresh for 60 seconds by default
        staleTime: 60_000,
        // Retry once on failure (default 3 is too aggressive)
        retry: 1,
        // Don't refetch on window focus in dev (annoying)
        refetchOnWindowFocus: process.env.NODE_ENV === 'production',
      },
      mutations: {
        retry: 0,
      },
    },
  })
}

let browserQueryClient: QueryClient | undefined

/**
 * Returns the singleton QueryClient for browser usage.
 * Creates it on first call. Safe to call in Client Components.
 */
export function getQueryClient(): QueryClient {
  if (typeof window === 'undefined') {
    // Server: always make a new client (prevents cross-request state sharing)
    return makeQueryClient()
  }
  // Browser: reuse the same client across renders
  browserQueryClient ??= makeQueryClient()
  return browserQueryClient
}

import type { LucideIcon } from 'lucide-react'
import {
  BookOpen,
  CalendarDays,
  Clock,
  Clock4,
  CreditCard,
  DollarSign,
  FileText,
  Globe,
  LayoutDashboard,
  List,
  MapPin,
  Package,
  Palette,
  Plug,
  Plus,
  Receipt,
  Settings,
  Shield,
  UserCircle,
  UserPlus,
  Users,
  Wand2,
  Wrench,
  Zap,
} from 'lucide-react'

export type NavRole = 'owner' | 'admin' | 'artist' | 'receptionist'
export type PlanTier = 'solo' | 'studio' | 'pro' | 'enterprise'

export interface NavItem {
  label: string
  href: string
  icon: LucideIcon
  requiredRoles: NavRole[]
  requiredPlan?: PlanTier
  featureKey?: string
  badge?: 'new' | 'beta'
}

export interface NavGroup {
  label: string
  items: NavItem[]
  condition?: 'always' | 'multi-location'
}

export const APP_NAV: NavGroup[] = [
  {
    label: 'STUDIO',
    items: [
      {
        label: 'Dashboard',
        href: '/dashboard',
        icon: LayoutDashboard,
