import { NextResponse, type NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'

/**
 * OAuth callback handler (PKCE + OAuth code exchange).
 *
 * Supabase redirects here after Google OAuth and password reset flows.
 * Exchanges the code for a session, then redirects to the appropriate page.
 */
export async function GET(request: NextRequest) {
  const { searchParams, origin } = new URL(request.url)
  const code = searchParams.get('code')
  const next = searchParams.get('next') ?? '/dashboard'
  const error = searchParams.get('error')
  const errorDescription = searchParams.get('error_description')

  // Handle OAuth errors from Supabase
  if (error ?? errorDescription) {
    const params = new URLSearchParams({ error: errorDescription ?? error ?? 'OAuth error' })
    return NextResponse.redirect(`${origin}/login?${params.toString()}`)
  }

  if (!code) {
    return NextResponse.redirect(`${origin}/login?error=Missing+authorization+code`)
  }

  const supabase = await createClient()
  const { error: exchangeError } = await supabase.auth.exchangeCodeForSession(code)

  if (exchangeError) {
    const params = new URLSearchParams({ error: exchangeError.message })
    return NextResponse.redirect(`${origin}/login?${params.toString()}`)
  }

  // Check if the user needs onboarding (no locations set up yet)
  const { data: { user } } = await supabase.auth.getUser()

  if (user) {
    // Get the user's studio
    const { data: member } = await supabase
      .from('studio_members')
      .select('studio_id')
      .eq('user_id', user.id)
      .single()

    if (member) {
      const { count } = await supabase
        .from('locations')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', member.studio_id)

      // No locations = new user who needs onboarding
      if (count === 0) {
        return NextResponse.redirect(`${origin}/onboarding`)
      }
    }
  }

  return NextResponse.redirect(`${origin}${next}`)
}

