const signupSchema = z.object({
  studioName: z.string().min(2, 'Studio name must be at least 2 characters').max(60),
  email: z.string().email('Enter a valid email'),
  password: z.string().min(8, 'Use 8 or more characters'),
})

type SignupValues = z.infer<typeof signupSchema>

function getPasswordStrength(password: string): { score: number; label: string } {
  if (!password) return { score: 0, label: '' }
  let score = 0
  if (password.length >= 8) score++
  if (/[A-Z]/.test(password)) score++
  if (/[0-9]/.test(password)) score++
  if (/[^A-Za-z0-9]/.test(password)) score++
  const labels = ['', 'Weak', 'Fair', 'Good', 'Strong']
  return { score, label: labels[score] ?? '' }
}

function PasswordStrengthBar({ password }: { password: string }) {
  const { score } = getPasswordStrength(password)
  if (!password) return null

  const widths = ['0%', '25%', '50%', '75%', '100%']
  const barColors = [
    '',
    'bg-destructive',
    'bg-amber-500',
    'bg-emerald-500',
    'bg-emerald-500',
  ]

  return (
    <div className="mt-1.5">
      <div className="h-1 w-full overflow-hidden rounded-full bg-border">
        <div
          className={cn('h-full rounded-full transition-all duration-300', barColors[score] ?? '')}
          style={{ width: widths[score] ?? '0%' }}
        />
      </div>
    </div>
  )
}

