'use client'

import { useState } from 'react'
import Link from 'next/link'
import { zodResolver } from '@hookform/resolvers/zod'
import { useForm } from 'react-hook-form'
import { z } from 'zod'
import { CheckCircle2, Loader2 } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { createClient } from '@/lib/supabase/client'

const forgotSchema = z.object({
  email: z.string().email('Enter a valid email'),
})

type ForgotValues = z.infer<typeof forgotSchema>

export function ForgotPasswordForm() {
  const [isSent, setIsSent] = useState(false)
  const [sentEmail, setSentEmail] = useState('')
  const [isSubmitting, setIsSubmitting] = useState(false)

  const {
    register,
    handleSubmit,
    getValues,
    formState: { errors },
  } = useForm<ForgotValues>({
    resolver: zodResolver(forgotSchema),
  })

  const sendReset = async (email: string) => {
    setIsSubmitting(true)
    const supabase = createClient()

    const { error } = await supabase.auth.resetPasswordForEmail(email, {
      redirectTo: `${window.location.origin}/auth/callback?next=/reset-password`,
    })

    setIsSubmitting(false)

    if (error) {
      toast.error(`Couldn't send reset link — try again`)
      return false
    }

    return true
  }

  const onSubmit = handleSubmit(async (values) => {
    const success = await sendReset(values.email)
    if (success) {
      setSentEmail(values.email)
      setIsSent(true)
      toast.success('Reset link sent — check your inbox')
    }
  })

  const handleResend = async () => {
    const email = getValues('email') || sentEmail
    await sendReset(email)
    toast.success('Reset link sent again')
  }

  if (isSent) {
    return (
      <div className="space-y-6 text-center">
        <div className="space-y-1">
          <div className="mb-4 flex justify-center">
            <CheckCircle2 className="h-12 w-12 text-primary" aria-hidden="true" />
          </div>
          <h1 className="text-2xl font-bold tracking-tight">Check your inbox</h1>
          <p className="text-sm text-muted-foreground">
            We sent a reset link to
          </p>
          <p className="text-sm font-medium text-foreground">{sentEmail}</p>
        </div>

        <Button variant="outline" className="w-full h-10" asChild>
          <Link href="/login">Back to sign in</Link>
        </Button>

        <p className="text-sm text-muted-foreground">
          Didn&apos;t get it?{' '}
          <button
            type="button"
            onClick={handleResend}
            className="text-primary hover:underline underline-offset-2"
          >
            Resend
          </button>
        </p>
      </div>
    )
  }

  return (
    <form onSubmit={onSubmit} noValidate className="space-y-5">
      {/* Heading */}
      <div className="space-y-1">
        <h1 className="text-2xl font-bold tracking-tight">Reset your password</h1>
        <p className="text-sm text-muted-foreground">
          Enter your email and we&apos;ll send a reset link
        </p>
      </div>

      {/* Email */}
      <div className="space-y-1.5">
        <Label htmlFor="email">Email address</Label>
        <Input
          id="email"
          type="email"
          autoComplete="email"
          placeholder="you@studio.com"
          aria-describedby={errors.email ? 'email-error' : undefined}
          aria-invalid={!!errors.email}
          {...register('email')}
        />
        {errors.email && (
          <p id="email-error" role="alert" className="text-xs text-destructive">
            {errors.email.message}
          </p>
        )}
      </div>

      {/* Submit */}
      <Button type="submit" className="w-full h-10" disabled={isSubmitting}>
        {isSubmitting && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
        Send reset link
      </Button>

      {/* Back link */}
      <p className="text-center text-sm">
        <Link href="/login" className="text-primary hover:underline underline-offset-2">
          ← Back to sign in
        </Link>
      </p>
    </form>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter, useSearchParams } from 'next/navigation'
import { zodResolver } from '@hookform/resolvers/zod'
import { useForm } from 'react-hook-form'
import { z } from 'zod'
import { Loader2 } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { createClient } from '@/lib/supabase/client'

const resetSchema = z
  .object({
    password: z.string().min(8, 'Use 8 or more characters'),
    confirmPassword: z.string().min(1, 'Please confirm your password'),
  })
  .refine((data) => data.password === data.confirmPassword, {
    message: 'Passwords do not match',
    path: ['confirmPassword'],
  })

type ResetValues = z.infer<typeof resetSchema>

export function ResetPasswordForm() {
  const router = useRouter()
  const searchParams = useSearchParams()
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [errorMessage, setErrorMessage] = useState<string>('')
  const [sessionReady, setSessionReady] = useState(false)

  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<ResetValues>({
    resolver: zodResolver(resetSchema),
  })

  // Exchange the code for a session when the component mounts
  useEffect(() => {
    const code = searchParams.get('code')
    if (!code) {
      setErrorMessage('Invalid or expired reset link. Please request a new one.')
      return
    }

    const supabase = createClient()
    supabase.auth.exchangeCodeForSession(code).then(({ error }) => {
      if (error) {
        setErrorMessage('Invalid or expired reset link. Please request a new one.')
      } else {
        setSessionReady(true)
      }
    })
  }, [searchParams])

  const onSubmit = handleSubmit(async (values) => {
    if (!sessionReady) return
    setIsSubmitting(true)
    setErrorMessage('')
    const supabase = createClient()

    const { error } = await supabase.auth.updateUser({
      password: values.password,
    })

    setIsSubmitting(false)

    if (error) {
      setErrorMessage(error.message)
      return
    }

    toast.success('Password updated — sign in with your new password')
    router.push('/dashboard')
    router.refresh()
  })

  return (
    <form onSubmit={onSubmit} noValidate className="space-y-5">
      {/* Heading */}
      <div className="space-y-1">
        <h1 className="text-2xl font-bold tracking-tight">Choose a new password</h1>
        <p className="text-sm text-muted-foreground">
          Make it strong — your studio depends on it
        </p>
      </div>

      {/* New password */}
      <div className="space-y-1.5">
        <Label htmlFor="password">New password</Label>
        <Input
          id="password"
          type="password"
          autoComplete="new-password"
          aria-describedby={errors.password ? 'password-error' : undefined}
          aria-invalid={!!errors.password}
          disabled={!sessionReady}
          {...register('password')}
        />
        {errors.password && (
          <p id="password-error" role="alert" className="text-xs text-destructive">
            {errors.password.message}
          </p>
        )}
      </div>

      {/* Confirm password */}
      <div className="space-y-1.5">
        <Label htmlFor="confirmPassword">Confirm new password</Label>
        <Input
          id="confirmPassword"
          type="password"
          autoComplete="new-password"
          aria-describedby={errors.confirmPassword ? 'confirm-password-error' : undefined}
          aria-invalid={!!errors.confirmPassword}
          disabled={!sessionReady}
          {...register('confirmPassword')}
        />
        {errors.confirmPassword && (
          <p id="confirm-password-error" role="alert" className="text-xs text-destructive">
            {errors.confirmPassword.message}
          </p>
        )}
      </div>

      {/* Error */}
      {errorMessage && (
        <p role="alert" className="text-sm text-destructive">
          {errorMessage}
        </p>
      )}

      {/* Submit */}
      <Button
        type="submit"
        className="w-full h-10"
        disabled={isSubmitting || !sessionReady}
      >
        {isSubmitting && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
        Update password
      </Button>
    </form>
  )
}

import type { LucideIcon } from 'lucide-react'
import Link from 'next/link'
import { Button } from '@/components/ui/button'

interface EmptyStateCta {
  label: string
  onClick?: () => void
  href?: string
}

interface EmptyStateProps {
  icon: LucideIcon
  title: string
  description?: string
  cta?: EmptyStateCta
  ctaSecondary?: EmptyStateCta
  variant?: 'default' | 'filtered'
}

function CtaButton({ cta }: { cta: EmptyStateCta }) {
  if (cta.href) {
    return (
      <Button size="sm" asChild>
        <Link href={cta.href}>{cta.label}</Link>
      </Button>
    )
  }
  return (
    <Button size="sm" onClick={cta.onClick}>
      {cta.label}
    </Button>
  )
}

function SecondaryCtaButton({ cta }: { cta: EmptyStateCta }) {
  if (cta.href) {
    return (
      <Button size="sm" variant="outline" asChild>
        <Link href={cta.href}>{cta.label}</Link>
      </Button>
    )
  }
  return (
    <Button size="sm" variant="outline" onClick={cta.onClick}>
      {cta.label}
    </Button>
  )
}

export function EmptyState({
  icon: Icon,
  title,
  description,
  cta,
  ctaSecondary,
}: EmptyStateProps) {
  return (
    <div className="flex flex-col items-center justify-center py-16 text-center">
      <div className="mb-4 rounded-xl bg-muted/50 p-4">
        <Icon className="mx-auto h-12 w-12 text-muted-foreground/40" aria-hidden="true" />
      </div>
      <h3 className="mb-1 text-base font-semibold">{title}</h3>
      {description && (
        <p className="mb-6 max-w-[280px] text-sm text-muted-foreground">{description}</p>
      )}
      {(cta ?? ctaSecondary) && (
        <div className="flex flex-wrap items-center justify-center gap-2">
          {cta && <CtaButton cta={cta} />}
          {ctaSecondary && <SecondaryCtaButton cta={ctaSecondary} />}
        </div>
      )}
    </div>
  )
}

'use client'

import type { LucideIcon } from 'lucide-react'
import { Card, CardContent, CardHeader } from '@/components/ui/card'
import { cn } from '@/lib/utils'

interface KpiCardProps {
  label: string
  value: string | number
  subtext: string
  icon: LucideIcon
  trend?: 'up' | 'down' | 'neutral'
  /** When true, lower value is better (e.g., no-show rate). Inverts trend color logic. */
  invertTrend?: boolean
  loading?: boolean
  index?: number
}

function getTrendColor(trend: 'up' | 'down' | 'neutral', invertTrend: boolean): string {
  if (trend === 'neutral') return 'text-muted-foreground'
  const isPositive = invertTrend ? trend === 'down' : trend === 'up'
  return isPositive ? 'text-emerald-500' : 'text-destructive'
}

export function KpiCard({
  label,
  value,
  subtext,
  icon: Icon,
  trend = 'neutral',
  invertTrend = false,
  index = 0,
}: KpiCardProps) {
  return (
    <Card
      className="kpi-card-hover border-border/50 shadow-[var(--shadow-card)] animate-fade-in-up"
      style={{
        animationDelay: `${index * 80}ms`,
        animationFillMode: 'both',
      }}
    >
      <CardHeader className="flex flex-row items-center justify-between pb-2 pt-4 px-4">
        <span className="text-xs font-semibold uppercase tracking-widest text-muted-foreground">
          {label}
        </span>
        <Icon className="h-4 w-4 text-muted-foreground/60 shrink-0" aria-hidden="true" />
      </CardHeader>
      <CardContent className="px-4 pb-4">
        <div className="text-2xl font-bold tabular-nums">{value}</div>
        <p className={cn('mt-1 text-xs', getTrendColor(trend, invertTrend))}>{subtext}</p>
      </CardContent>
    </Card>
  )
}

