'use client'

import { CalendarOff } from 'lucide-react'
import Link from 'next/link'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'

export interface ScheduleAppointment {
  id: string
  clientName: string
  service: string
  startHour: number   // 0-23
  startMinute: number // 0-59
  durationMin: number
  artistInitials?: string
  status?: 'confirmed' | 'in-progress' | 'pending'
}

interface ScheduleTimelineProps {
  appointments?: ScheduleAppointment[]
  loading?: boolean
}

const HOUR_START = 8
const HOUR_END = 20
const TOTAL_HOURS = HOUR_END - HOUR_START

function toPercent(hour: number, minute: number): number {
  return ((hour - HOUR_START + minute / 60) / TOTAL_HOURS) * 100
}

function durationPercent(durationMin: number): number {
  return (durationMin / 60 / TOTAL_HOURS) * 100
}

function ScheduleItem({ appt }: { appt: ScheduleAppointment }) {
  const left = toPercent(appt.startHour, appt.startMinute)
  const width = Math.max(durationPercent(appt.durationMin), 8) // min 8% so it's clickable

  return (
    <div
      role="listitem"
      className="absolute top-1 bottom-1 rounded-md border-l-2 border-primary bg-primary/[0.08] px-2 py-1 overflow-hidden min-w-[64px]"
      style={{ left: `${left}%`, width: `${width}%` }}
      title={`${appt.clientName} · ${appt.service}`}
    >
      <p className="truncate text-xs font-medium text-foreground leading-tight">
        {appt.clientName}
      </p>
      <p className="truncate text-[10px] text-muted-foreground leading-tight">
        {appt.service}
      </p>
    </div>
  )
}

export function ScheduleTimeline({ appointments, loading }: ScheduleTimelineProps) {
  if (loading) {
    return (
      <div className="rounded-xl border border-border/50 bg-card p-5 shadow-[var(--shadow-card)]">
        <div className="mb-4 flex items-center justify-between">
          <Skeleton className="h-5 w-36" />
          <Skeleton className="h-8 w-28" />
        </div>
        <div className="flex flex-col gap-3">
          <Skeleton className="h-12 w-full rounded-md" />
          <Skeleton className="h-12 w-full rounded-md" />
          <Skeleton className="h-12 w-full rounded-md" />
        </div>
      </div>
    )
  }

  const hours = Array.from({ length: TOTAL_HOURS + 1 }, (_, i) => HOUR_START + i)

  return (
    <div className="rounded-xl border border-border/50 bg-card p-5 shadow-[var(--shadow-card)]">
      <div className="mb-4 flex items-center justify-between">
        <h2 className="text-base font-semibold">Today&#39;s Schedule</h2>
        <Button variant="outline" size="sm" asChild>
          <Link href="/appointments/new">New Booking</Link>
        </Button>
      </div>

      {!appointments || appointments.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-10">
          <CalendarOff className="mb-3 h-8 w-8 text-muted-foreground/40" aria-hidden="true" />
          <p className="text-sm text-muted-foreground">No appointments today</p>
        </div>
      ) : (
        <div className="overflow-x-auto">
          <div className="min-w-[520px]">
            {/* Hour markers */}
            <div className="relative mb-1 flex" aria-hidden="true">
              {hours.map((h) => (
                <div
                  key={h}
                  className="flex-1 text-[10px] text-muted-foreground/60"
                  style={{ minWidth: 0 }}
                >
                  {h === HOUR_END
                    ? null
                    : `${h > 12 ? h - 12 : h}${h >= 12 ? 'pm' : 'am'}`}
                </div>
              ))}
            </div>

            {/* Timeline track */}
            <div
              role="list"
              aria-label="Today's appointments"
              className="relative h-14 rounded-md bg-muted/20"
            >
              {/* Vertical hour dividers */}
              {hours.slice(0, -1).map((h, i) => (
                <div
                  key={h}
                  aria-hidden="true"
                  className="absolute inset-y-0 w-px bg-border/20"
                  style={{ left: `${(i / TOTAL_HOURS) * 100}%` }}
                />
              ))}

              {appointments.map((appt) => (
                <ScheduleItem key={appt.id} appt={appt} />
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import { AlertCircle, AlertTriangle, CheckCircle2 } from 'lucide-react'
import Link from 'next/link'
import { Skeleton } from '@/components/ui/skeleton'
import { Badge } from '@/components/ui/badge'

export interface Alert {
  id: string
  severity: 'warning' | 'error'
  message: string
  detail?: string
  href?: string
  actionLabel?: string
}

interface AlertsCardProps {
  alerts?: Alert[]
  loading?: boolean
}

export function AlertsCard({ alerts, loading }: AlertsCardProps) {
  if (loading) {
    return (
      <div className="rounded-xl border border-border/50 bg-card p-5 shadow-[var(--shadow-card)]">
        <div className="mb-4 flex items-center gap-2">
          <Skeleton className="h-5 w-16" />
          <Skeleton className="h-5 w-6 rounded-full" />
        </div>
        <div className="flex flex-col gap-3">
          <Skeleton className="h-14 w-full rounded-md" />
          <Skeleton className="h-14 w-full rounded-md" />
        </div>
      </div>
    )
  }

  const count = alerts?.length ?? 0

  return (
    <div className="rounded-xl border border-border/50 bg-card p-5 shadow-[var(--shadow-card)]">
      <div className="mb-4 flex items-center gap-2">
        <h2 className="text-base font-semibold">Alerts</h2>
        {count > 0 && (
          <Badge
            variant="secondary"
            className="h-5 min-w-5 justify-center rounded-full px-1.5 text-[11px] font-semibold"
          >
            {count}
          </Badge>
        )}
      </div>

      {count === 0 ? (
        <div className="flex flex-col items-center justify-center py-6">
          <CheckCircle2
            className="mb-2 h-8 w-8 text-emerald-500"
            aria-hidden="true"
          />
          <p className="text-sm font-medium text-center">All clear</p>
          <p className="text-xs text-muted-foreground text-center mt-0.5">
            No outstanding alerts
          </p>
        </div>
      ) : (
        <ul className="flex flex-col divide-y divide-border/40">
          {alerts!.map((alert) => (
            <li key={alert.id} className="flex items-start gap-3 py-3 first:pt-0 last:pb-0">
              {alert.severity === 'warning' ? (
                <AlertTriangle
                  className="mt-0.5 h-4 w-4 shrink-0 text-amber-500"
                  aria-hidden="true"
                />
              ) : (
                <AlertCircle
                  className="mt-0.5 h-4 w-4 shrink-0 text-destructive"
                  aria-hidden="true"
                />
              )}
              <div className="min-w-0 flex-1">
                <p className="text-sm font-medium leading-snug">{alert.message}</p>
                {alert.detail && (
                  <p className="text-xs text-muted-foreground">{alert.detail}</p>
                )}
                {alert.href && alert.actionLabel && (
                  <Link
                    href={alert.href}
                    className="text-xs text-primary hover:underline underline-offset-2"
                  >
                    {alert.actionLabel}
                  </Link>
                )}
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

'use client'

import {
  type ColumnDef,
  flexRender,
  getCoreRowModel,
  useReactTable,
} from '@tanstack/react-table'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'
import { ChevronLeft, ChevronRight } from 'lucide-react'

// Import table components from shadcn — these may not be installed yet;
// we declare the minimal shape inline so the file compiles regardless.
// When `pnpm dlx shadcn@latest add table` is run, replace this block.
// For now, lightweight inline table primitives:

interface DataTableProps<TData, TValue> {
  columns: ColumnDef<TData, TValue>[]
  data: TData[]
  loading?: boolean
  /** Total row count for server-side pagination */
  rowCount?: number
  /** Current 0-based page index */
  pageIndex?: number
  /** Rows per page */
  pageSize?: number
  onPageChange?: (newPage: number) => void
  /** Accessible label */
  caption?: string
}

export function DataTable<TData, TValue>({
  columns,
  data,
  loading,
  rowCount,
  pageIndex = 0,
  pageSize = 20,
  onPageChange,
  caption,
}: DataTableProps<TData, TValue>) {
  const table = useReactTable({
    data,
    columns,
    getCoreRowModel: getCoreRowModel(),
    manualPagination: true,
    rowCount: rowCount ?? data.length,
    state: {
      pagination: { pageIndex, pageSize },
    },
  })

  const totalPages = Math.ceil((rowCount ?? data.length) / pageSize)
  const hasPrev = pageIndex > 0
  const hasNext = pageIndex + 1 < totalPages

  return (
    <div className="rounded-xl border border-border/50 bg-card shadow-[var(--shadow-card)]">
      <div className="overflow-x-auto">
        <table className="w-full caption-bottom text-sm" aria-label={caption}>
          <thead>
            {table.getHeaderGroups().map((headerGroup) => (
              <tr
                key={headerGroup.id}
                className="border-b border-border/40"
              >
                {headerGroup.headers.map((header) => (
                  <th
                    key={header.id}
                    className="h-10 px-4 text-left align-middle text-[11px] font-semibold uppercase tracking-widest text-muted-foreground/70 first:pl-5 last:pr-5"
                  >
                    {header.isPlaceholder
                      ? null
                      : flexRender(
                          header.column.columnDef.header,
                          header.getContext(),
                        )}
                  </th>
                ))}
              </tr>
            ))}
          </thead>
          <tbody>
            {loading ? (
              Array.from({ length: pageSize > 5 ? 5 : pageSize }).map((_, i) => (
                <tr key={i} className="border-b border-border/30 last:border-0">
                  {columns.map((_, j) => (
                    <td key={j} className="h-12 px-4 first:pl-5 last:pr-5">
                      <Skeleton className="h-3 w-full" />
                    </td>
                  ))}
                </tr>
              ))
            ) : table.getRowModel().rows.length === 0 ? (
              <tr>
                <td
                  colSpan={columns.length}
                  className="h-32 text-center text-sm text-muted-foreground"
                >
                  No results
                </td>
              </tr>
            ) : (
              table.getRowModel().rows.map((row) => (
                <tr
                  key={row.id}
                  className="border-b border-border/30 last:border-0 hover:bg-muted/30 transition-colors"
                >
                  {row.getVisibleCells().map((cell) => (
                    <td
                      key={cell.id}
                      className="h-12 px-4 align-middle first:pl-5 last:pr-5"
                    >
                      {flexRender(cell.column.columnDef.cell, cell.getContext())}
                    </td>
                  ))}
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {onPageChange && totalPages > 1 && (
        <div className="flex items-center justify-between border-t border-border/40 px-5 py-3">
          <p className="text-xs text-muted-foreground">
            Page {pageIndex + 1} of {totalPages}
            {rowCount != null && ` · ${rowCount} total`}
          </p>
          <div className="flex gap-1">
            <Button
              variant="ghost"
              size="icon"
              className="h-8 w-8"
              disabled={!hasPrev || loading}
              onClick={() => onPageChange(pageIndex - 1)}
              aria-label="Previous page"
            >
              <ChevronLeft className="h-4 w-4" />
            </Button>
            <Button
              variant="ghost"
              size="icon"
              className="h-8 w-8"
              disabled={!hasNext || loading}
              onClick={() => onPageChange(pageIndex + 1)}
              aria-label="Next page"
            >
              <ChevronRight className="h-4 w-4" />
            </Button>
          </div>
        </div>
      )}
    </div>
  )
}

// Re-export table primitives for convenience
export {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
}

'use client'

import { ChevronLeft, ChevronRight } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'
import { cn } from '@/lib/utils'

// Sprint 1: lightweight DataTable without @tanstack/react-table.
// Swapped for full TanStack Table in Sprint 2.

export interface Column<TData> {
  key: string
  header: string
  cell: (row: TData) => React.ReactNode
  headerClassName?: string
  cellClassName?: string
}

interface DataTableProps<TData> {
  columns: Column<TData>[]
  data: TData[]
  loading?: boolean
  /** Total row count for server-side pagination */
  rowCount?: number
  /** Current 0-based page index */
  pageIndex?: number
  /** Rows per page */
  pageSize?: number
  onPageChange?: (newPage: number) => void
  caption?: string
}

export function DataTable<TData extends { id: string }>({
  columns,
  data,
  loading,
  rowCount,
  pageIndex = 0,
  pageSize = 20,
  onPageChange,
  caption,
}: DataTableProps<TData>) {
  const total = rowCount ?? data.length
  const totalPages = Math.ceil(total / pageSize)
  const hasPrev = pageIndex > 0
  const hasNext = pageIndex + 1 < totalPages

  return (
    <div className="rounded-xl border border-border/50 bg-card shadow-[var(--shadow-card)]">
      <div className="overflow-x-auto">
        <table className="w-full text-sm" aria-label={caption}>
          <thead>
            <tr className="border-b border-border/40">
              {columns.map((col) => (
                <th
                  key={col.key}
                  className={cn(
                    'h-10 px-4 text-left align-middle text-[11px] font-semibold uppercase tracking-widest text-muted-foreground/70 first:pl-5 last:pr-5',
                    col.headerClassName,
                  )}
                >
                  {col.header}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {loading ? (
              Array.from({ length: Math.min(pageSize, 5) }).map((_, i) => (
                <tr key={i} className="border-b border-border/30 last:border-0">
                  {columns.map((col) => (
                    <td key={col.key} className="h-12 px-4 first:pl-5 last:pr-5">
                      <Skeleton className="h-3 w-full" />
                    </td>
                  ))}
                </tr>
              ))
            ) : data.length === 0 ? (
              <tr>
                <td
                  colSpan={columns.length}
                  className="h-32 text-center text-sm text-muted-foreground"
                >
                  No results
                </td>
              </tr>
            ) : (
              data.map((row) => (
                <tr
                  key={row.id}
                  className="border-b border-border/30 last:border-0 transition-colors hover:bg-muted/30"
                >
                  {columns.map((col) => (
                    <td
                      key={col.key}
                      className={cn(
                        'h-12 px-4 align-middle first:pl-5 last:pr-5',
                        col.cellClassName,
                      )}
                    >
                      {col.cell(row)}
                    </td>
                  ))}
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {onPageChange && totalPages > 1 && (
        <div className="flex items-center justify-between border-t border-border/40 px-5 py-3">
          <p className="text-xs text-muted-foreground">
            Page {pageIndex + 1} of {totalPages}
            {rowCount != null && ` · ${rowCount.toLocaleString()} total`}
          </p>
          <div className="flex gap-1">
            <Button
              variant="ghost"
              size="icon"
              className="h-8 w-8"
              disabled={!hasPrev || loading}
              onClick={() => onPageChange(pageIndex - 1)}
              aria-label="Previous page"
            >
              <ChevronLeft className="h-4 w-4" />
            </Button>
            <Button
              variant="ghost"
              size="icon"
              className="h-8 w-8"
              disabled={!hasNext || loading}
              onClick={() => onPageChange(pageIndex + 1)}
              aria-label="Next page"
            >
              <ChevronRight className="h-4 w-4" />
            </Button>
          </div>
        </div>
      )}
    </div>
  )
}

