'use client'

import { usePathname } from 'next/navigation'
import Link from 'next/link'
import {
  SidebarGroup,
  SidebarGroupLabel,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
} from '@/components/ui/sidebar'
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '@/components/ui/tooltip'
import { Badge } from '@/components/ui/badge'
import type { NavGroup } from '@/components/app/sidebar/nav-config'
import { hasFeature } from '@/lib/billing/feature-gate'
import type { PlanTier } from '@/lib/billing/feature-gate'

interface SidebarNavGroupProps {
  group: NavGroup
  plan: PlanTier
}

export function SidebarNavGroup({ group, plan }: SidebarNavGroupProps) {
  const pathname = usePathname()

  return (
    <SidebarGroup>
      <SidebarGroupLabel className="group-data-[collapsible=icon]:hidden">
        {group.label}
      </SidebarGroupLabel>
      <SidebarMenu>
        {group.items.map((item) => {
          const isActive =
            item.href === '/dashboard'
              ? pathname === '/dashboard'
              : pathname.startsWith(item.href)

          const isGated =
            !!item.requiredPlan &&
            !!item.featureKey &&
            !hasFeature(plan, item.featureKey)

          return (
            <SidebarMenuItem key={item.href}>
              <Tooltip>
                <TooltipTrigger asChild>
                  <SidebarMenuButton
                    asChild
                    isActive={isActive}
                    className="h-10 gap-3 rounded-md px-3 text-sm font-medium"
                  >
                    <Link href={item.href}>
                      <item.icon
                        className="!h-[18px] !w-[18px] shrink-0 text-sidebar-foreground/60"
                        aria-hidden="true"
                      />
                      <span className="group-data-[collapsible=icon]:hidden">
                        {item.label}
                      </span>
                      {isGated && (
                        <Badge className="ml-auto h-4 bg-primary/15 px-1.5 py-0 text-[9px] text-primary border-primary/20 group-data-[collapsible=icon]:hidden">
                          Pro
                        </Badge>
                      )}
                      {item.badge && !isGated && (
                        <Badge className="ml-auto h-4 bg-emerald-500/15 px-1.5 py-0 text-[9px] text-emerald-500 border-emerald-500/20 group-data-[collapsible=icon]:hidden">
                          {item.badge === 'new' ? 'New' : 'Beta'}
                        </Badge>
                      )}
                    </Link>
                  </SidebarMenuButton>
                </TooltipTrigger>
                <TooltipContent side="right" className="group-data-[state=expanded]:hidden">
                  {item.label}
                  {isGated && ' (Pro)'}
                </TooltipContent>
              </Tooltip>
            </SidebarMenuItem>
          )
        })}
      </SidebarMenu>
    </SidebarGroup>
  )
}

