'use client'

import { useQuery } from '@tanstack/react-query'
import { queryKeys } from '@/lib/query-keys'
import type { ScheduleAppointment } from '@/components/shared/ScheduleTimeline'

async function fetchTodaySchedule(
  studioId: string,
  date: string,
): Promise<ScheduleAppointment[]> {
  const res = await fetch(
    `/api/dashboard/schedule?studioId=${encodeURIComponent(studioId)}&date=${encodeURIComponent(date)}`,
  )
  if (!res.ok) throw new Error('Failed to fetch schedule')
  return res.json() as Promise<ScheduleAppointment[]>
}

export function useTodaySchedule(studioId: string | null) {
  const today = new Date().toISOString().split('T')[0]

  return useQuery({
    queryKey: queryKeys.dashboard.schedule(studioId ?? '', today),
    queryFn: () => fetchTodaySchedule(studioId!, today),
    enabled: !!studioId,
    staleTime: 60_000,
    retry: 1,
    placeholderData: [] as ScheduleAppointment[],
  })
}

'use client'

import { useQuery } from '@tanstack/react-query'
import { queryKeys } from '@/lib/query-keys'
import type { ActivityEvent } from '@/components/shared/ActivityFeed'

async function fetchRecentActivity(studioId: string): Promise<ActivityEvent[]> {
  const res = await fetch(
    `/api/dashboard/activity?studioId=${encodeURIComponent(studioId)}`,
  )
  if (!res.ok) throw new Error('Failed to fetch activity')
  return res.json() as Promise<ActivityEvent[]>
}

export function useRecentActivity(studioId: string | null) {
  return useQuery({
    queryKey: queryKeys.dashboard.activity(studioId ?? ''),
    queryFn: () => fetchRecentActivity(studioId!),
    enabled: !!studioId,
    staleTime: 60_000,
    retry: 1,
    placeholderData: [] as ActivityEvent[],
  })
}
